import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Box, Button, Dialog, DialogTitle, DialogContent, DialogContentText, DialogActions } from '@mui/material';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import Navbar from './Navbar_Student';
import StudentLeftSidebar from './StudentLeftSidebar';
import BackIcon from '../assets/back.png';
import { readToolkitContentByScope, writeToolkitContentByScope } from '../utils/ragflowChatHistory';


const buttonSx = {
  width: '140px',
  height: '44px',
  minWidth: '140px',
  fontSize: '18px',
  fontWeight: 700,
  backgroundColor: '#FFFFFF',
  color: '#000000',
  border: '2px solid #000000',
  borderRadius: '999px',
  boxShadow: 'none',
  '&:hover': {
    backgroundColor: '#ece8e5',
    boxShadow: 'none',
  },
};

const ensureQuillLoaded = () => {
  return new Promise((resolve, reject) => {
    if (window.Quill) {
      resolve();
      return;
    }

    const cssId = 'quill-snow-css';
    if (!document.getElementById(cssId)) {
      const link = document.createElement('link');
      link.id = cssId;
      link.rel = 'stylesheet';
      link.href = 'https://cdn.jsdelivr.net/npm/quill@1.3.7/dist/quill.snow.css';
      document.head.appendChild(link);
    }

    const scriptId = 'quill-js';
    const existing = document.getElementById(scriptId);
    if (existing) {
      existing.addEventListener('load', () => resolve());
      existing.addEventListener('error', () => reject(new Error('Failed to load Quill')));
      return;
    }

    const script = document.createElement('script');
    script.id = scriptId;
    script.src = 'https://cdn.jsdelivr.net/npm/quill@1.3.7/dist/quill.min.js';
    script.async = true;
    script.onload = () => resolve();
    script.onerror = () => reject(new Error('Failed to load Quill'));
    document.body.appendChild(script);
  });
};

const notionApiBases = [
  process.env.REACT_APP_NOTION_API_BASE_URL,
  '/api/notion',
  '/notion-api',
  'http://localhost:4000',
  'http://140.115.126.27:4000',
].filter(Boolean);
const WRITING_ANALYSIS_PREFILL_KEY = 'writingAnalysisPrefillPrompt';

const upsertEssayToNotion = async (payload) => {
  const token = localStorage.getItem('jwtToken');
  const headers = token ? { Authorization: `Bearer ${token}` } : {};
  let lastError = null;

  for (const base of notionApiBases) {
    const normalizedBase = base.replace(/\/+$/, '');
    const url = `${normalizedBase}/api/update-note`;

    try {
      await axios.patch(url, payload, {
        timeout: 15000,
        headers,
      });
      return;
    } catch (error) {
      lastError = error;
    }
  }

  throw lastError || new Error('Notion request failed');
};

const fetchEssayFromNotion = async ({ studentName, className, theme }) => {
  const token = localStorage.getItem('jwtToken');
  const headers = token ? { Authorization: `Bearer ${token}` } : {};
  let lastError = null;

  for (const base of notionApiBases) {
    const normalizedBase = base.replace(/\/+$/, '');
    const url = `${normalizedBase}/api/get-essay/${encodeURIComponent(studentName)}`;

    try {
      const response = await axios.get(url, {
        timeout: 15000,
        headers,
        params: { className, theme },
      });
      return response?.data?.data || null;
    } catch (error) {
      const isBackendJson =
        error?.response &&
        typeof error.response.data === 'object' &&
        error.response.data !== null &&
        Object.prototype.hasOwnProperty.call(error.response.data, 'success');
      if (error?.response?.status === 404 && isBackendJson) {
        const notFoundError = new Error('NOT_FOUND');
        notFoundError.code = 'NOT_FOUND';
        throw notFoundError;
      }
      lastError = error;
    }
  }

  throw lastError || new Error('Fetch essay from Notion failed');
};

const buildEssayStorageKey = (studentName, className, theme) =>
  `essayData::${encodeURIComponent(studentName || '')}::${encodeURIComponent(className || '')}::${encodeURIComponent(theme || '')}`;
const buildSubmitLockKey = (studentName, className, theme) =>
  `submitLocked::${encodeURIComponent(studentName || '')}::${encodeURIComponent(className || '')}::${encodeURIComponent(theme || '')}`;
const buildToolkitScope = (studentName, className, theme) => ({
  studentName: studentName || '',
  className: className || '',
  topicName: theme || '',
});
const countEnglishWords = (htmlContent) => {
  if (!htmlContent) return 0;
  const plainText = htmlContent
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!plainText) return 0;
  const matches = plainText.match(/[A-Za-z]+(?:['’-][A-Za-z]+)*/g);
  return matches ? matches.length : 0;
};

const convertEditorHtmlToPlainText = (htmlContent) => {
  if (!htmlContent) return '';

  const htmlWithLineBreaks = String(htmlContent)
    .replace(/<\s*br\s*\/?>/gi, '\n')
    .replace(/<\s*\/(p|div|h[1-6]|li|tr)\s*>/gi, '\n')
    .replace(/<\s*li\b[^>]*>/gi, '- ');

  const tempElement = document.createElement('div');
  tempElement.innerHTML = htmlWithLineBreaks;

  return (tempElement.textContent || tempElement.innerText || '')
    .replace(/\u00a0/g, ' ')
    .replace(/\r\n?/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
};

const WritingArea = () => {
  const navigate = useNavigate();
  const [editorContent, setEditorContent] = useState('');
  const [studentName, setStudentName] = useState('');
  const [activityTitle, setActivityTitle] = useState('');
  const [groupName, setGroupName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [isCompletedEntry, setIsCompletedEntry] = useState(false);
  const [openConfirmSubmitDialog, setOpenConfirmSubmitDialog] = useState(false);
  const [kfSummaryContent, setKfSummaryContent] = useState('');
  const [outlineContent, setOutlineContent] = useState('');
  const [notesContent, setNotesContent] = useState('');

  const quillRootRef = useRef(null);
  const quillInstanceRef = useRef(null);
  const englishWordCount = useMemo(() => countEnglishWords(editorContent), [editorContent]);
  const isReadOnly = isSubmitted || isCompletedEntry;

  const resolveCurrentScopeValues = () => {
    const currentStudentName =
      localStorage.getItem('name') ||
      localStorage.getItem('username') ||
      localStorage.getItem('userName') ||
      studentName ||
      '';
    const className = activityTitle || localStorage.getItem('activityTitle') || '';
    const theme = groupName || localStorage.getItem('groupName') || '';
    const toolkitScope = buildToolkitScope(currentStudentName, className, theme);
    return { currentStudentName, className, theme, toolkitScope };
  };

  useEffect(() => {
    let mounted = true;
    const loadInitialData = async () => {
      const savedStudentName = localStorage.getItem('name') || '';
      const savedActivityTitle = localStorage.getItem('activityTitle') || '';
      const savedGroupName = localStorage.getItem('groupName') || '';
      const completedEntry =
        localStorage.getItem('isCompletedActivityEntry') === 'true' ||
        localStorage.getItem('activityEntryStatus') === 'completed';
      const scopedEssayKey = buildEssayStorageKey(savedStudentName, savedActivityTitle, savedGroupName);
      const scopedSavedEssay = localStorage.getItem(scopedEssayKey) || '';
      const scopedSubmitLockKey = buildSubmitLockKey(savedStudentName, savedActivityTitle, savedGroupName);
      const scopedSubmitLocked = localStorage.getItem(scopedSubmitLockKey) === 'true';
      const toolkitScope = buildToolkitScope(savedStudentName, savedActivityTitle, savedGroupName);
      const savedKfSummary = readToolkitContentByScope('kfAnalysisData', toolkitScope);
      const savedOutline = readToolkitContentByScope('outlineData', toolkitScope);
      const savedNotes = readToolkitContentByScope('noteData', toolkitScope);

      if (!mounted) return;
      setStudentName(savedStudentName);
      setActivityTitle(savedActivityTitle);
      setGroupName(savedGroupName);
      setEditorContent(scopedSavedEssay);
      setIsSubmitted(scopedSubmitLocked);
      setIsCompletedEntry(completedEntry);
      setKfSummaryContent(savedKfSummary);
      setOutlineContent(savedOutline);
      setNotesContent(savedNotes);

      if (!savedStudentName || !savedActivityTitle || !savedGroupName) {
        setEditorContent('');
        return;
      }

      try {
        const notionData = await fetchEssayFromNotion({
          studentName: savedStudentName,
          className: savedActivityTitle,
          theme: savedGroupName,
        });

        const fetchedEssay = typeof notionData?.essayContent === 'string' ? notionData.essayContent : '';
        const fetchedKfSummary =
          typeof notionData?.kfAnalysisContent === 'string' ? notionData.kfAnalysisContent : '';
        const fetchedOutline =
          typeof notionData?.outlineContent === 'string' ? notionData.outlineContent : '';
        const fetchedNotes = typeof notionData?.noteContent === 'string' ? notionData.noteContent : '';
        if (!mounted) return;

        setEditorContent(fetchedEssay);
        setKfSummaryContent(fetchedKfSummary);
        setOutlineContent(fetchedOutline);
        setNotesContent(fetchedNotes);
        localStorage.setItem(scopedEssayKey, fetchedEssay);
        localStorage.setItem('essayData', fetchedEssay);
        localStorage.setItem('editorData', fetchedEssay);
        writeToolkitContentByScope('kfAnalysisData', fetchedKfSummary, toolkitScope);
        writeToolkitContentByScope('outlineData', fetchedOutline, toolkitScope);
        writeToolkitContentByScope('noteData', fetchedNotes, toolkitScope);
      } catch (error) {
        if (!mounted) return;
        if (error?.code === 'NOT_FOUND' || error?.response?.status === 404) {
          setEditorContent('');
          setKfSummaryContent('');
          setOutlineContent('');
          setNotesContent('');
          localStorage.removeItem(scopedEssayKey);
          localStorage.removeItem('essayData');
          localStorage.removeItem('editorData');
          writeToolkitContentByScope('kfAnalysisData', '', toolkitScope);
          writeToolkitContentByScope('outlineData', '', toolkitScope);
          writeToolkitContentByScope('noteData', '', toolkitScope);
          return;
        }
        console.error('從 Notion 載入議論文失敗，改用該主題本機資料:', error);
      }
    };

    loadInitialData();
    return () => {
      mounted = false;
    };
  }, []);

  useEffect(() => {
    let mounted = true;

    const init = async () => {
      try {
        await ensureQuillLoaded();
        if (!mounted || !quillRootRef.current) return;

        if (quillInstanceRef.current) {
          quillInstanceRef.current.enable(!isReadOnly);
          return;
        }

        const Quill = window.Quill;
        const quill = new Quill(quillRootRef.current, {
          theme: 'snow',
          modules: {
            toolbar: [
              [{ size: ['small', false, 'large', 'huge'] }],
              ['bold', 'italic', 'underline', 'strike'],
              [{ color: [] }, { background: [] }],
              [{ list: 'ordered' }, { list: 'bullet' }],
              [{ align: [] }],
              ['link', 'image'],
              ['clean'],
            ],
          },
          placeholder: '',
        });

        quill.root.style.fontSize = '16px';
        quill.root.innerHTML = editorContent || '';
        quill.enable(!isReadOnly);

        quill.on('text-change', () => {
          setEditorContent(quill.root.innerHTML);
        });

        quillInstanceRef.current = quill;
      } catch (error) {
        console.error(error);
      }
    };

    init();

    return () => {
      mounted = false;
    };
  }, [isReadOnly]);

  useEffect(() => {
    const quill = quillInstanceRef.current;
    if (!quill) return;
    if (quill.root.innerHTML === (editorContent || '')) return;
    quill.root.innerHTML = editorContent || '';
  }, [editorContent]);

  const syncEssayToNotion = async ({ submissionStatus } = {}) => {
    const { currentStudentName, className, theme, toolkitScope } = resolveCurrentScopeValues();
    const scopedEssayKey = buildEssayStorageKey(currentStudentName, className, theme);

    localStorage.setItem(scopedEssayKey, editorContent);
    localStorage.setItem('essayData', editorContent);
    localStorage.setItem('editorData', editorContent);
    writeToolkitContentByScope('kfAnalysisData', kfSummaryContent, toolkitScope);
    writeToolkitContentByScope('outlineData', outlineContent, toolkitScope);
    writeToolkitContentByScope('noteData', notesContent, toolkitScope);

    if (!currentStudentName || !className || !theme) {
      alert('已先儲存到本機，但缺少姓名、班級或主題，無法同步到 Notion。');
      return false;
    }

    const rawChatHistory = localStorage.getItem('chatHistory');
    let chatHistoryPayload = [];
    if (rawChatHistory) {
      try {
        chatHistoryPayload = JSON.parse(rawChatHistory);
      } catch {
        chatHistoryPayload = [];
      }
    }

    try {
      setIsSaving(true);
      await upsertEssayToNotion({
        studentName: currentStudentName,
        className,
        theme,
        essayContent: editorContent,
        noteContent: notesContent || '',
        kfAnalysisContent: kfSummaryContent || '',
        outlineContent: outlineContent || '',
        ...(submissionStatus ? { submissionStatus } : {}),
        chatHistory: chatHistoryPayload,
      });
      return true;
    } catch (error) {
      console.error('同步到 Notion 失敗:', error);
      const errorMessage = error?.response?.data?.error || error?.message || '未知錯誤';
      alert(`已先儲存到本機，但同步 Notion 失敗：${errorMessage}`);
      return false;
    } finally {
      setIsSaving(false);
    }
  };

  const handleSave = async () => {
    if (isReadOnly) return;
    const saveSucceeded = await syncEssayToNotion();
    if (saveSucceeded) {
      alert('Saved successfully. Before submitting, you can go to Writing Analysis mode to check the quality of your argumentative essay.');
    }
  };

  const handleSubmit = async () => {
    if (isReadOnly) return false;
    return syncEssayToNotion({ submissionStatus: '是' });
  };

  const handleConfirmSubmit = async () => {
    if (isReadOnly) return;

    const { currentStudentName, className, theme } = resolveCurrentScopeValues();
    const scopedSubmitLockKey = buildSubmitLockKey(currentStudentName, className, theme);

    const submitSucceeded = await handleSubmit();
    if (!submitSucceeded) return;

    localStorage.setItem(scopedSubmitLockKey, 'true');
    setIsSubmitted(true);
    setOpenConfirmSubmitDialog(false);
    alert('Submission successful!');
  };

  const handleGoToChatbotMode = (chatbotEntryMode) => {
    if (chatbotEntryMode === 'writing_analysis') {
      const essayPlainText = convertEditorHtmlToPlainText(editorContent);
      if (essayPlainText) {
        sessionStorage.setItem(WRITING_ANALYSIS_PREFILL_KEY, essayPlainText);
      } else {
        sessionStorage.removeItem(WRITING_ANALYSIS_PREFILL_KEY);
      }
    } else {
      sessionStorage.removeItem(WRITING_ANALYSIS_PREFILL_KEY);
    }

    sessionStorage.setItem('chatbotEntryMode', chatbotEntryMode);
    navigate('/Chatbotlogin', { state: { chatbotEntryMode } });
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Navbar />
      <Box
        sx={{
          flex: 1,
          minHeight: 0,
          display: 'flex',
          justifyContent: 'flex-start',
          alignItems: 'stretch',
          p: 0,
          backgroundColor: '#ffffff',
        }}
      >
        <Box
          sx={{
            width: '100%',
            display: 'flex',
            alignItems: 'stretch',
            gap: 0,
            minHeight: '100%',
          }}
        >
          <StudentLeftSidebar />

          <Box
            sx={{
              flex: 1,
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              gap: 0,
              p: 2,
            }}
          >
            <Box
              sx={{
                width: '80%',
                mx: 'auto',
                display: 'flex',
                alignItems: 'flex-start',
                gap: 1.5,
              }}
            >
              <Button
                variant="text"
                onClick={() => window.history.back()}
                sx={{
                  minWidth: 0,
                  p: 0,
                  mt: 1,
                  width: '44px',
                  height: '44px',
                  borderRadius: '8px',
                  '&:hover': {
                    backgroundColor: 'rgba(105, 83, 83, 0.12)',
                  },
                }}
              >
                <img src={BackIcon} alt="Back" style={{ width: '32px', height: '32px' }} />
              </Button>

              <Box
                sx={{
                  flex: 1,
                  border: '2px solid #000000',
                  borderRadius: '8px',
                  backgroundColor: '#ffffff',
                  overflow: 'hidden',
                  display: 'flex',
                  flexDirection: 'column',
                  '& .class-topic-text': {
                    fontSize: '22px !important',
                    lineHeight: 1.2,
                  },
                  '& .ql-toolbar.ql-snow': {
                    border: 'none',
                    borderTop: '1px solid #bdbdbd',
                    borderBottom: '1px solid #ddd',
                    backgroundColor: '#ffffff !important',
                  },
                  '& .ql-container.ql-snow': {
                    border: 'none',
                    minHeight: '500px',
                    backgroundColor: '#ffffff !important',
                  },
                  '& .ql-editor': {
                    minHeight: '500px',
                    fontSize: '16px',
                    paddingBottom: '44px',
                    backgroundColor: '#ffffff !important',
                  },
                }}
              >
                <Box
                  sx={{
                    width: '100%',
                    backgroundColor: '#ffffff',
                    display: 'flex',
                    flexDirection: 'column',
                    fontSize: '22px',
                    fontWeight: 600,
                  }}
                >
                  <Box sx={{ px: 2, pt: 1.5, pb: 1, display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                    <span className="class-topic-text">Student: {studentName || '-'}</span>
                    <span className="class-topic-text">Class: {activityTitle || '-'}</span>
                    <span className="class-topic-text">Topic: {groupName || '-'}</span>
                  </Box>
                </Box>
                <Box sx={{ position: 'relative', backgroundColor: '#ffffff' }}>
                  <div ref={quillRootRef} style={{ backgroundColor: '#ffffff' }} />
                  <Box
                    sx={{
                      position: 'absolute',
                      right: 14,
                      bottom: 10,
                      px: 1,
                      py: 0.35,
                      borderRadius: '999px',
                      border: '1px solid #c9c9c9',
                      backgroundColor: 'rgba(255, 255, 255, 0.95)',
                      color: '#444',
                      fontSize: '13px',
                      fontWeight: 600,
                      lineHeight: 1,
                      pointerEvents: 'none',
                      zIndex: 1,
                    }}
                  >
                    Words: {englishWordCount}
                  </Box>
                </Box>
              </Box>
            </Box>

            <Box
              sx={{
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                gap: 2,
                flexWrap: 'wrap',
                mt: 2,
              }}
            >
              <Button variant="contained" onClick={handleSave} sx={buttonSx} disabled={isSaving || isReadOnly}>
                {isSaving ? 'Saving...' : 'Save'}
              </Button>
              <Button
                variant="contained"
                onClick={() => handleGoToChatbotMode('writing_analysis')}
                sx={buttonSx}
              >
                Analysis
              </Button>
              <Button variant="contained" onClick={() => setOpenConfirmSubmitDialog(true)} sx={buttonSx} disabled={isSaving || isReadOnly}>
                Submit
              </Button>
            </Box>
          </Box>
        </Box>
      </Box>

      <Dialog open={openConfirmSubmitDialog} onClose={() => setOpenConfirmSubmitDialog(false)}>
        <DialogTitle sx={{ fontWeight: 700, fontSize: '22px' }}>Confirm Submission</DialogTitle>
        <DialogContent>
          <DialogContentText sx={{ fontWeight: 700, fontSize: '18px', color: 'text.primary' }}>
            Are you sure you want to submit? Once submitted, you cannot resubmit.
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenConfirmSubmitDialog(false)} color="primary">
            Cancel
          </Button>
          <Button onClick={handleConfirmSubmit} color="primary" autoFocus disabled={isSaving}>
            Submission
          </Button>
        </DialogActions>
      </Dialog>
    </div>
  );
};

export default WritingArea;
